def transform(grid):
    from collections import Counter
    h,w=len(grid),len(grid[0]); bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    out=[row[:] for row in grid]; seen=set()
    for r in range(h):
      for c in range(w):
        color=grid[r][c]
        if color==bg or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); cells=[]
        while stack:
          y,x=stack.pop(); cells.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
              seen.add((yy,xx)); stack.append((yy,xx))
        r0=min(y for y,x in cells); r1=max(y for y,x in cells); c0=min(x for y,x in cells); c1=max(x for y,x in cells)
        # Fill enclosed non-background intrusions when component represents a rectangular patch.
        if len(cells)>=4:
          for y in range(r0,r1+1):
            for x in range(c0,c1+1):
              if grid[y][x]!=bg: out[y][x]=color
    return out
